This Terraform configuration creates an AWS RDS MySQL database instance. It uses the default VPC and its subnets, creates a security group allowing MySQL access on port `3306`, and configures the RDS instance so that any supported changes are applied immediately using `apply_immediately = true`.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the MySQL RDS instance will be created."
  type        = string
  default     = "us-east-1"
}

variable "db_instance_identifier" {
  description = "Identifier for the RDS MySQL instance."
  type        = string
  default     = "terraform-mysql-instance"
}

variable "db_name" {
  description = "Initial database name."
  type        = string
  default     = "appdb"
}

variable "db_username" {
  description = "Master username for the MySQL database."
  type        = string
  default     = "adminuser"
}

